struct Book {
  std::vector<int> v{100, 101, 102};
  const std::vector<int>& get() const {
    return v; }
};
Book load_book() { return {}; }
int main() {
  long sum = 0;
  for (int n : load_book().get())
    sum += n;
  std::cout << sum << '\n';
}

// OK: direct member access extends
// the whole Book temporary
for (int n : load_book().v)
  sum += n;

// OK: C++20 init-statement owns it
for (auto b = load_book(); int n : b.get())
  sum += n;

struct Order { std::string id; int qty; };
int main() {
  std::vector<Order> orders;
  orders.push_back({"ord1", 100});
  const Order& first = orders[0];
  orders.push_back({"ord2", 200});
  std::cout << first.qty << '\n';
}

orders.push_back({"ord1", 100});
std::size_t first = 0;   // index, not &
